const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const contentId = String($json.content_id ?? '').trim();
const title = String($json.title ?? '').trim();
const narrationScript = String($json.narration_script ?? '').trim();
if (!uuidPattern.test(contentId)) {
  throw new Error('Fetch Next Script Complete Item did not produce a valid content_id. Ensure a script_complete row exists and run from the start.');
}
if (!title) {
  throw new Error('Fetch Next Script Complete Item did not produce a title.');
}
if (!narrationScript) {
  throw new Error('Fetch Next Script Complete Item did not produce a narration_script.');
}
return [{
  json: {
    content_id: contentId,
    title,
    category: String($json.category ?? 'general'),
    target_duration_seconds: Number($json.target_duration_seconds ?? 45),
    narration_script: narrationScript,
    short_script: String($json.short_script ?? ''),
    onscreen_text_json: $json.onscreen_text_json ?? [],
    brand_tone: 'cinematic, concise, credible',
    visual_style_rules: 'realistic, moody, high contrast, cinematic composition, vertical-frame friendly',
    subtitle_style_rules: 'short lines, high contrast, mobile readable, centered safely above app UI',
    llm_instruction: 'Convert this narration into a storyboard package with scenes, subtitles, a cover prompt, and a render manifest seed.',
    status_after_success: 'storyboard_complete'
  }
}];

return [{
  json: {
    content_id: $json.content_id,
    title: $json.title,
    category: $json.category,
    target_duration_seconds: $json.target_duration_seconds,
    prompt: {
      instruction: $json.llm_instruction,
      narration_script: $json.narration_script,
      brand_tone: $json.brand_tone,
      visual_style_rules: $json.visual_style_rules,
      subtitle_style_rules: $json.subtitle_style_rules,
      response_schema: {
        storyboard_json: [
          {
            scene_number: 1,
            duration_seconds: 4,
            narration_text: 'string',
            visual_prompt: 'string',
            asset_type: 'image|video',
            transition: 'string',
            mood: 'string'
          }
        ],
        cover_prompt: 'string',
        subtitle_lines_json: [
          {
            scene_number: 1,
            text: 'string'
          }
        ],
        style_notes: 'string',
        visual_style_summary: 'string',
        render_manifest_seed_json: {
          output: {
            width: 1080,
            height: 1920,
            fps: 30,
            format: 'mp4'
          },
          timeline: [],
          subtitles: {
            enabled: true,
            style: 'default_story_subtitles'
          }
        }
      }
    },
    status_after_success: $json.status_after_success
  }
}];

if (!$json.content_id || !$json.title || !$json.prompt?.narration_script) {
  throw new Error('Build Storyboard Request did not produce the required context for storyboard generation.');
}
const rawSegments = $json.prompt.narration_script
  .split(/(?<=[.!?])\s+/)
  .map((segment) => segment.trim())
  .filter(Boolean);
const segments = rawSegments.length >= 4
  ? rawSegments.slice(0, 6)
  : [
      rawSegments[0] ?? $json.title,
      rawSegments[1] ?? `The core question around ${$json.title}`,
      rawSegments[2] ?? 'The details that keep the story alive.',
      rawSegments[3] ?? 'Why the debate never fully ends.'
    ];
const baseDuration = Math.max(3, Number(($json.target_duration_seconds / segments.length).toFixed(1)));
const storyboardJson = segments.map((segment, index) => ({
  scene_number: index + 1,
  duration_seconds: baseDuration,
  narration_text: segment,
  visual_prompt: `${$json.title}, ${segment}, cinematic vertical composition, ${index % 2 === 0 ? 'moody realism' : 'atmospheric detail'}, high contrast, story-driven frame`,
  asset_type: index % 2 === 0 ? 'video' : 'image',
  transition: index === 0 ? 'cut' : 'fade',
  mood: index === 0 ? 'intrigue' : index === segments.length - 1 ? 'reflection' : 'tension'
}));
const subtitleLines = storyboardJson.map((scene) => ({
  scene_number: scene.scene_number,
  text: scene.narration_text
}));
const renderManifestSeed = {
  output: {
    width: 1080,
    height: 1920,
    fps: 30,
    format: 'mp4'
  },
  timeline: storyboardJson.map((scene) => ({
    scene_number: scene.scene_number,
    duration_seconds: scene.duration_seconds,
    asset_type: scene.asset_type,
    transition: scene.transition
  })),
  subtitles: {
    enabled: true,
    style: 'default_story_subtitles'
  }
};
return [{
  json: {
    content_id: $json.content_id,
    title: $json.title,
    status_after_success: $json.status_after_success,
    storyboard_response: {
      storyboard_json: storyboardJson,
      cover_prompt: `${$json.title}, bold focal point, cinematic mystery cover, vertical composition, high contrast, minimal clutter`,
      subtitle_lines_json: subtitleLines,
      style_notes: `Tone: ${$json.prompt.brand_tone}. Visual rules: ${$json.prompt.visual_style_rules}. Subtitle rules: ${$json.prompt.subtitle_style_rules}.`,
      visual_style_summary: 'Cinematic vertical realism with restrained motion, high contrast framing, and readable mobile-first subtitle timing.',
      render_manifest_seed_json: renderManifestSeed
    }
  }
}];

const response = $json.storyboard_response ?? {};
if (!$json.content_id) {
  throw new Error('Mock Storyboard Response did not provide content_id.');
}
if (!Array.isArray(response.storyboard_json) || response.storyboard_json.length === 0) {
  throw new Error('Mock Storyboard Response did not produce storyboard_json.');
}
return [{
  json: {
    content_id: $json.content_id,
    status_after_success: $json.status_after_success,
    storyboard_json: response.storyboard_json,
    cover_prompt: response.cover_prompt,
    subtitle_lines_json: response.subtitle_lines_json,
    style_notes: `${response.style_notes}\n\nVisual style summary: ${response.visual_style_summary}`,
    render_manifest_seed_json: response.render_manifest_seed_json,
    raw_storyboard_json: response
  }
}];

const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const contentId = String($json.content_id ?? '').trim();
if (!uuidPattern.test(contentId)) {
  throw new Error(`Prepare Storyboard SQL Values received an invalid content_id: ${contentId || '<empty>'}.`);
}
return [{
  json: {
    ...$json,
    content_id_sql: contentId,
    storyboard_json_sql: JSON.stringify($json.storyboard_json ?? []).replaceAll("'", "''"),
    cover_prompt_sql: String($json.cover_prompt ?? '').replaceAll("'", "''"),
    subtitle_lines_json_sql: JSON.stringify($json.subtitle_lines_json ?? []).replaceAll("'", "''"),
    style_notes_sql: String($json.style_notes ?? '').replaceAll("'", "''"),
    render_manifest_seed_json_sql: JSON.stringify($json.render_manifest_seed_json ?? {}).replaceAll("'", "''")
  }
}];
